const UserList = () => {
  const { data, loading } = useFetch(getUsers.setPayload({ limit: 10 }));

  if (loading) return <p>Loading...</p>;
  return (
    <ul>
      {data?.users.map((u) => (
        <li key={u.id}>{u.name}</li>
      ))}
    </ul>
  );
};
